#!/usr/bin/env python3
import base64,gzip,json
from pathlib import Path
DATA=base64.b64decode("""""")
obj=json.loads(gzip.decompress(DATA).decode('utf-8'))
out=Path('data/uppcs_test1.json')
out.parent.mkdir(parents=True,exist_ok=True)
out.write_text(json.dumps(obj,ensure_ascii=False,indent=2),encoding='utf-8')
print('✅ UPPCS Test 1 installed:',out)
print('Questions:',len(obj['questions']))
print('Medium:',obj['medium'])
print('Answer conflicts flagged:',[q['id'] for q in obj['questions'] if q.get('answerConflict')])
